// Generates src/data/map.v1.ts from the canonical schema/map.v1.json at the repository root
// (or HARNESS_MAP_SCHEMA). `--check` fails when the generated file is out of date.
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { compileFromFile } from 'json-schema-to-typescript'
import prettier from 'prettier'

const here = path.dirname(fileURLToPath(import.meta.url))
const schema = path.resolve(process.env.HARNESS_MAP_SCHEMA ?? path.join(here, '../../../schema/map.v1.json'))
const out = path.join(here, '../src/data/map.v1.ts')
const check = process.argv.includes('--check')

if (!fs.existsSync(schema)) {
  console.log(`Schema not found at ${schema}; set HARNESS_MAP_SCHEMA to generate the map types.`)
  process.exit(check ? 0 : 1)
}

const banner = '/* Generated by scripts/gen-types.mjs from schema/map.v1.json. Do not edit; run `pnpm gen:types`. */'
const raw = await compileFromFile(schema, { bannerComment: banner, format: false, cwd: path.dirname(schema) })
const ts = await prettier.format(raw, { ...(await prettier.resolveConfig(out)), filepath: out })

if (check) {
  const current = fs.existsSync(out) ? fs.readFileSync(out, 'utf8') : ''
  if (current !== ts) {
    console.error('src/data/map.v1.ts is out of date with the schema; run `pnpm gen:types`.')
    process.exit(1)
  }
} else {
  fs.writeFileSync(out, ts)
}
